import React, { createContext, useContext, useState, useRef, useEffect } from 'react';

type AudioTrack = 'landing' | 'game' | 'none';

interface AudioContextType {
  currentTrack: AudioTrack;
  isPlaying: boolean;
  volume: number;
  isMuted: boolean;
  playLandingMusic: () => Promise<boolean>;
  playGameMusic: () => Promise<boolean>;
  stopMusic: () => void;
  togglePlay: () => void;
  setVolume: (volume: number) => void;
  toggleMute: () => void;
}

const AudioContext = createContext<AudioContextType>({
  currentTrack: 'none',
  isPlaying: false,
  volume: 0.5,
  isMuted: false,
  playLandingMusic: async () => false,
  playGameMusic: async () => false,
  stopMusic: () => {},
  togglePlay: () => {},
  setVolume: () => {},
  toggleMute: () => {},
});

export const useAudio = () => useContext(AudioContext);

export const AudioProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentTrack, setCurrentTrack] = useState<AudioTrack>('none');
  const [isPlaying, setIsPlaying] = useState(false);
  const [volume, setVolumeState] = useState(0.5);
  const [isMuted, setIsMuted] = useState(false);
  
  const landingAudioRef = useRef<HTMLAudioElement | null>(null);
  const gameAudioRef = useRef<HTMLAudioElement | null>(null);
  const hasInteractedRef = useRef(false);
  const interactionBoundRef = useRef(false);
  
  // Inicializar elementos de audio
  useEffect(() => {
    landingAudioRef.current = new Audio('/assets/audio/landing-theme.mp3');
    gameAudioRef.current = new Audio('/assets/audio/game-theme.mp3');
    
    // Configurar para que se repitan
    if (landingAudioRef.current) landingAudioRef.current.loop = true;
    if (gameAudioRef.current) gameAudioRef.current.loop = true;
    
    // Cargar preferencias de usuario del localStorage
    const savedVolume = localStorage.getItem('audioVolume');
    const savedMuted = localStorage.getItem('audioMuted');
    
    if (savedVolume) setVolumeState(parseFloat(savedVolume));
    if (savedMuted) setIsMuted(savedMuted === 'true');
    
    // Función para iniciar música después de interacción
    const initAudioAfterInteraction = () => {
      if (!hasInteractedRef.current) {
        hasInteractedRef.current = true;
        
        // Intentar reproducir la música de la landing si estamos en la ruta adecuada
        if (window.location.pathname === '/' || 
            window.location.pathname === '/login' || 
            window.location.pathname === '/register') {
          playLandingMusic();
        } else {
          playGameMusic();
        }
        
        // Limpiar los event listeners
        document.removeEventListener('click', initAudioAfterInteraction);
        document.removeEventListener('keydown', initAudioAfterInteraction);
        document.removeEventListener('touchstart', initAudioAfterInteraction);
      }
    };
    
    // Agregar event listeners para detectar interacción
    if (!interactionBoundRef.current) {
      document.addEventListener('click', initAudioAfterInteraction);
      document.addEventListener('keydown', initAudioAfterInteraction);
      document.addEventListener('touchstart', initAudioAfterInteraction);
      interactionBoundRef.current = true;
    }
    
    // Cleanup al desmontar
    return () => {
      document.removeEventListener('click', initAudioAfterInteraction);
      document.removeEventListener('keydown', initAudioAfterInteraction);
      document.removeEventListener('touchstart', initAudioAfterInteraction);
      
      if (landingAudioRef.current) {
        landingAudioRef.current.pause();
        landingAudioRef.current = null;
      }
      if (gameAudioRef.current) {
        gameAudioRef.current.pause();
        gameAudioRef.current = null;
      }
    };
  }, []);
  
  // Aplicar volumen y mute a los elementos de audio
  useEffect(() => {
    if (landingAudioRef.current) {
      landingAudioRef.current.volume = isMuted ? 0 : volume;
    }
    if (gameAudioRef.current) {
      gameAudioRef.current.volume = isMuted ? 0 : volume;
    }
    
    // Guardar preferencias en localStorage
    localStorage.setItem('audioVolume', volume.toString());
    localStorage.setItem('audioMuted', isMuted.toString());
  }, [volume, isMuted]);
  
  // Pausar todas las pistas
  const pauseAllTracks = () => {
    if (landingAudioRef.current) landingAudioRef.current.pause();
    if (gameAudioRef.current) gameAudioRef.current.pause();
    setIsPlaying(false);
  };
  
  // Reproducir música de la landing page
  const playLandingMusic = async (): Promise<boolean> => {
    if (!hasInteractedRef.current) {
      console.warn("No se puede reproducir audio sin interacción del usuario");
      return false;
    }
    
    pauseAllTracks();
    
    if (landingAudioRef.current) {
      try {
        landingAudioRef.current.currentTime = 0;
        await landingAudioRef.current.play();
        setCurrentTrack('landing');
        setIsPlaying(true);
        return true;
      } catch (err) {
        console.error('Error reproduciendo música de landing:', err);
        return false;
      }
    }
    return false;
  };
  
  // Reproducir música del juego
  const playGameMusic = async (): Promise<boolean> => {
    if (!hasInteractedRef.current) {
      console.warn("No se puede reproducir audio sin interacción del usuario");
      return false;
    }
    
    pauseAllTracks();
    
    if (gameAudioRef.current) {
      try {
        gameAudioRef.current.currentTime = 0;
        await gameAudioRef.current.play();
        setCurrentTrack('game');
        setIsPlaying(true);
        return true;
      } catch (err) {
        console.error('Error reproduciendo música del juego:', err);
        return false;
      }
    }
    return false;
  };
  
  // Detener toda la música
  const stopMusic = () => {
    pauseAllTracks();
    setCurrentTrack('none');
  };
  
  // Alternar reproducción/pausa
  const togglePlay = () => {
    if (isPlaying) {
      pauseAllTracks();
    } else {
      if (currentTrack === 'landing') playLandingMusic();
      else if (currentTrack === 'game') playGameMusic();
      else playLandingMusic(); // Por defecto, reproducir landing si no hay track seleccionado
    }
  };
  
  // Ajustar volumen
  const setVolume = (newVolume: number) => {
    setVolumeState(newVolume);
  };
  
  // Alternar silencio
  const toggleMute = () => {
    setIsMuted(!isMuted);
  };
  
  const value = {
    currentTrack,
    isPlaying,
    volume,
    isMuted,
    playLandingMusic,
    playGameMusic,
    stopMusic,
    togglePlay,
    setVolume,
    toggleMute,
  };
  
  return (
    <AudioContext.Provider value={value}>
      {children}
    </AudioContext.Provider>
  );
};
